package io.github.limuyang2.router

import androidx.navigation3.runtime.EntryProviderScope
import io.github.limuyang2.router.info.ParseRouterInfo
import kotlin.reflect.KClass

/**
 * 模块级静态路由注册表，通常由 KSP 生成并通过聚合入口注册。
 *
 * Static module route registry, normally generated by KSP and registered through the aggregate entry point.
 */
interface ModuleRouter {
    /**
     * 路由类型到解析信息的映射
     *
     * Mapping from route classes to their parsing information.
     */
    fun routeMasterKV(): Map<KClass<*>, ParseRouterInfo>

    /**
     * 不含查询参数的路由 URL 到类型的映射
     *
     * Mapping from query-free route URLs to route classes.
     */
    fun routeAliasesKV(): Map<String, KClass<*>>

    /**
     * 模块贡献的全局 Push 拦截器及优先级
     *
     * Global push interceptors and priorities contributed by this module.
     */
    fun globalPushInterceptors(): List<GlobalPushInterceptorInfo>

    /**
     * 模块贡献的全局 Pop 拦截器及优先级
     *
     * Global pop interceptors and priorities contributed by this module.
     */
    fun globalPopInterceptors(): List<GlobalPopInterceptorInfo>

    /**
     * 返回安装本模块 NavEntry 定义的代码
     *
     * Returns the installer defining this module's NavEntries.
     */
    fun entryProviderInstaller(): EntryProviderInstaller
}

/**
 * 在 Nav3 entryProvider 作用域安装页面的函数
 *
 * Function installing pages in a Nav3 entryProvider scope.
 */
typealias EntryProviderInstaller = EntryProviderScope<Any>.() -> Unit
